import json
d=json.load(open('lg.json'))
out=[]
def walk(n):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='heading': out.append('\n\n## '+n.get('text','')+'\n')
        elif t=='paragraph':
            out.append('\n')
            for c in n.get('inlineContent',[]): walk(c)
            out.append('\n')
        elif t=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        else:
            for k in ('content','inlineContent','items','sections','primaryContentSections','abstract'):
                if k in n: walk(n[k])
    elif isinstance(n,list):
        for i in n: walk(i)
walk(d.get('primaryContentSections',[]))
txt=''.join(out)
open('lg.txt','w').write(txt)
